package build

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/generated/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "build"
	command.Identifiers = []string{"build"}
	command.Category = "Core Commands"
	command.Help = "Build the project in a directory"
	command.LongDescription = "Re-renders every generated file of the project in the given\ndirectory, then hands the result to the runtime named by\n--runtime (\"go\" resolves the module graph and compiles every\npackage, \"none\" renders only). If no path is provided, the\ncurrent directory is used.\n"
	command.Examples = []string{"build", "build --path ./my-project", "build -q"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"build --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"build -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
		{
			Id:          "runtime",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the toolchain the rendered project is handed to: go (tidy + compile) or none",
			Examples:    []string{"build --runtime none"},
			Default:     "go",
			HasDefault:  true,
			Identifiers: []string{"--runtime"},
		},
		{
			Id:          "unsafe",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Skips the verify schema gate before building",
			Examples:    []string{"build --unsafe"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--unsafe"},
		},
	}

	command.Args = []api.CommandArg{}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
